// UserDataDir returns the default root directory for user-specific data files.
// On Linux/Unix, it respects XDG_DATA_HOME (defaulting to ~/.local/share).
// On macOS (Darwin), it returns ~/Library/Application Support.
// On Windows, it returns %LocalAppData% (falling back to %AppData%).
func UserDataDir() (string, error) {
	if runtime.GOOS == "windows" {
		if local := os.Getenv("LOCALAPPDATA"); local != "" {
			return local, nil
		}
		return os.UserConfigDir()
	}
	if runtime.GOOS == "darwin" {
		home, err := os.UserHomeDir()
		if err != nil {
			return "", err
		}
		return filepath.Join(home, "Library", "Application Support"), nil
	}
	if xdg := os.Getenv("XDG_DATA_HOME"); xdg != "" {
		return xdg, nil
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(home, ".local", "share"), nil
}

